```
 #include <stdio.h>
 #include <iostream>
 #include <thread>

 #include <mavsdk/mavsdk.h>


 int main(int argc, char **argv)
 {
     mavsdk::Mavsdk mavsdk{mavsdk::Mavsdk::Configuration{mavsdk::ComponentType::CompanionComputer}};
     std::optional<std::shared_ptr<mavsdk::System>> system;

     printf("Connecting...\n");
     mavsdk::ConnectionResult connection_result = mavsdk.add_any_connection("tcp://127.0.0.1:5760");
     if (connection_result != mavsdk::ConnectionResult::Success)
     {
         std::cerr << "Connection failed: " << connection_result << '\n';
         exit(1);
     }

     printf("Waiting for system...\n");
     system = mavsdk.first_autopilot(3.0);
     if (!system)
     {
         std::cerr << "Timed out waiting for system\n";
         exit(1);
     }

     printf("Done\n");

     // Yield
     while (true)
     {
         std::this_thread::sleep_for(std::chrono::milliseconds(1000));
     }
 }
```

